<script setup lang="ts">import {computed,watch} from 'vue';const props=defineProps<{total:number;page:number;size:number;search?:string;searchPlaceholder?:string;footer?:boolean}>();const emit=defineEmits(['update:page','update:size','update:search']);const pages=computed(()=>props.size<0?1:Math.max(1,Math.ceil(props.total/props.size)));const start=computed(()=>props.total?((props.size<0?0:(props.page-1)*props.size)+1):0);const end=computed(()=>props.size<0?props.total:Math.min(props.page*props.size,props.total));watch(pages,n=>{if(props.page>n)emit('update:page',n);});</script><template><div v-if="!footer" class="pms-datatable-controls"><label>Show <select :value="size" aria-label="Rows per page" @change="emit('update:size',Number(($event.target as HTMLSelectElement).value));emit('update:page',1)"><option v-for="n in [10,25,50,100,-1]" :key="n" :value="n">{{n<0?'All':n}}</option></select> entries</label><div class="pms-datatable-search"><slot/><label>Search:<input :value="search" aria-label="Search table" :placeholder="searchPlaceholder" @input="emit('update:search',($event.target as HTMLInputElement).value);emit('update:page',1)"></label></div></div><div v-else class="pms-datatable-footer"><span>Showing {{start}} to {{end}} of {{total}} entries</span><div class="pms-pagination"><button :disabled="page<=1" @click="emit('update:page',page-1)">Previous</button><button v-for="n in pages" v-show="n===1||n===pages||Math.abs(n-page)<3" :key="n" :class="{active:n===page}" @click="emit('update:page',n)">{{n}}</button><button :disabled="page>=pages" @click="emit('update:page',page+1)">Next</button></div></div></template>